CREATE TABLE [sales].[POSShift]([ShiftId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_POSShift_Id] DEFAULT NEWSEQUENTIALID(),[CounterId] UNIQUEIDENTIFIER NOT NULL,[OpenedBy] NVARCHAR(256) NOT NULL,[OpenedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_POSShift_Opened] DEFAULT SYSUTCDATETIME(),[OpeningCash] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_POSShift_OpeningCash] DEFAULT 0,[ClosedBy] NVARCHAR(256) NULL,[ClosedOn] DATETIMEOFFSET NULL,[ClosingCash] DECIMAL(18,2) NULL,[Status] NVARCHAR(20) NOT NULL CONSTRAINT [DF_POSShift_Status] DEFAULT 'OPEN',[RowVersion] ROWVERSION NOT NULL,CONSTRAINT [PK_POSShift] PRIMARY KEY([ShiftId]),CONSTRAINT [FK_POSShift_Counter] FOREIGN KEY([CounterId]) REFERENCES [sales].[POSCounters]([CounterId]),CONSTRAINT [CK_POSShift_Status] CHECK([Status] IN('OPEN','CLOSED')));
